-- =====================================================================
-- The academy's courses and their syllabi, as first entered in the ERP.
--
-- The eight courses the website used to list by hand (names, fees,
-- durations and photos from computer-course.html), and each one's
-- syllabus copied from its own course page. ADCA had no page: its
-- syllabus is DCA's office modules, four Tally modules, Cyber Cafe's
-- photo & document editing, four modules of the AI for Office page and
-- a final project.
--
-- Run after website-courses.sql and course-syllabus.sql. Safe to re-run:
-- a course whose code already exists is left alone, and a course that
-- already has modules gets no more.
-- =====================================================================

-- The eight courses the website listed by hand, now as ERP courses.
insert into public.courses ("id","organizationId","name","code","category","description","durationValue","durationUnit","baseFee","image","websitePage","showOnWebsite","isActive","updatedAt")
select gen_random_uuid()::text, public.website_organization(), v.name, v.code, v.cat, v.descr, v.months, 'MONTHS', v.fee, v.img, v.page, true, true, now()
from (values
  ('Google Suite',                     'GSUITE', 'COMPUTER',          'Google Docs, Sheets, Slides, Drive, Forms and Gmail for school, office and online work.', 2, 1999, '/image/gs.webp',         'google-office.html'),
  ('DCA With AI',                      'DCA',    'COMPUTER',          'Diploma in Computer Application: computer basics, MS Word, Excel, PowerPoint, internet and AI tools.', 3, 3499, '/image/dca.webp',        'ms-office.html'),
  ('Tally Prime With GST',             'TALLY',  'PROFESSIONAL',      'Accounting, GST, inventory, payroll and business reports in Tally Prime.', 3, 3499, '/image/tally.webp',      'tally-prime.html'),
  ('Cyber Cafe Management',            'CYBER',  'VOCATIONAL',        'Computer services, printing and scanning, online form processing, billing and running a cyber cafe.', 3, 3999, '/image/cyber.webp',      'cybercafe-mangement.html'),
  ('Hindi & English Typing',           'TYPING', 'SKILL_DEVELOPMENT', 'English and Hindi (Unicode, Inscript, Remington) touch typing with daily speed and accuracy practice.', 3, 3499, '/image/typing.webp',     'typing.html'),
  ('Back Office & Computer Operator',  'BOCO',   'VOCATIONAL',        'MS Word, Excel, PowerPoint, email, data entry, documentation and day-to-day back office work.', 3, 5499, '/image/backoffice.webp', 'back-office.html'),
  ('Data Entry Operator',              'DEO',    'VOCATIONAL',        'English and Hindi typing, Excel and Google Sheets, PDF handling, online data entry and MIS reports.', 3, 5499, '/image/deo.webp',        'deo.html'),
  ('ADCA With AI',                     'ADCA',   'COMPUTER',          'Advanced Diploma in Computer Application: office software, accounting, internet, design basics and AI tools.', 6, 6499, '/image/adca.webp',       null)
) as v(name, code, cat, descr, months, fee, img, page)
where not exists (select 1 from public.courses c where upper(c."code") = upper(v.code));

select jsonb_array_length(public.public_courses()) as on_website,
       (select string_agg("code" || ' ₹' || "baseFee"::int, ', ' order by "code") from public.courses where "deletedAt" is null) as courses;

-- Syllabi: one module per row, its chapters in order.

